from fractions import Fraction
from math import ceil, floor


def solve(case):
    witness = case['witness']
    def abstain(reason):
        return {'decision': reason, 'epoch': None, 'sigma_s': None, 'witness': witness}
    if case['basis'] != 'BJD_TDB' or case['anchor'] is None:
        return abstain('ABSTAIN_TIME_BASIS')
    if any(value is None for value in case['row']):
        return abstain('ABSTAIN_MISSING')
    t0, sigma_t0, period, sigma_period, duration = map(Fraction, case['row'])
    n = ceil((Fraction(case['anchor']) - t0) / period)
    # On rho in [-1, 1] the extreme variances are (s0 +/- n*sp)**2.
    effects = [abs(sigma_t0 + rho * n * sigma_period) * 86400 for rho in (-1, 1)]
    minimum, maximum = sorted(effects)
    target = 3600 * duration / 12
    if maximum <= target:
        decision = 'WITHIN'
    elif minimum > target:
        decision = 'EXCEEDS'
    else:
        decision = 'COVARIANCE_SENSITIVE'
    return {'decision': decision, 'epoch': n, 'sigma_s': [floor(minimum), ceil(maximum)], 'witness': witness}
